using System.Text.Json;
using VisionFramework;
using VisionEditor.Core;
using VisionPluginContracts;
using VisionPlugins.Calibration;
static class Program{
 static int checks;static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}
 static Dictionary<string,PortValue> Inputs()=>new(){["ImagePointX"]=PortValue.Numbers([10,20]),["ImagePointY"]=PortValue.Numbers([11,21]),["PhysicalPointX"]=PortValue.Numbers([1,2]),["PhysicalPointY"]=PortValue.Numbers([3,4]),["WorldRotateAngle"]=PortValue.Numbers([0,0])};
 [STAThread]static int Main(){try{
 foreach((string text,bool match) in new[]{(new string('a',511),true),(new string('a',512),false),(new string('é',255),true),(new string('é',256),false),("go\0ignored",true),("",true)}){var i=Inputs();i["Trigger"]=PortValue.TextArray([text,"other"]);i["TeachFlagInput"]=PortValue.TextArray([text,"different"]);Check(Run(i).Outputs["CalibCurIndex"].As<long>()==(match?0:2),"source512 UTF8/array first/nul boundary "+text.Length);}
 var missing=Inputs();missing["TeachFlagInput"]=PortValue.Text("go");Check(Run(missing).Outputs["CalibCurIndex"].As<long>()==2,"missing Trigger does not teach");var empty=Inputs();empty["Trigger"]=PortValue.TextArray([]);empty["TeachFlagInput"]=PortValue.Text("go");Check(Run(empty).Outputs["CalibCurIndex"].As<long>()==2,"empty text payload does not teach");
 foreach(string failed in new[]{"Trigger","TeachFlagInput","none"}){var calls=new List<string>();var result=Run(Inputs(),(n,index,cap)=>{calls.Add(n);Check(index==0&&cap==512,"original caller index0 capacity512");return new(n==failed?0xe0000012u:0,1,"go",3);});Check(calls.SequenceEqual(new[]{"Trigger","TeachFlagInput"}),"both reads retain original order even first fails");Check(result.Outputs["CalibCurIndex"].As<long>()==(failed=="none"?0:2),"error positive Count normalized to zero "+failed);}
 using(var scope=new ModuleExecutionScope()){var service=new Reader();scope.RegisterService<IToolTextInputReader>(service);var result=Run(Inputs(),(_,_,_)=>throw new Exception("scope reader must win"),scope);Check(service.Calls==2&&result.Outputs["CalibCurIndex"].As<long>()==0,"scope text reader overrides graph callback");}
 Graph();
 Console.WriteLine($"PASS {checks} Npoint original512-byte teaching text checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static ModuleResult Run(Dictionary<string,PortValue> input,Func<string,int,int,ModuleTextInputReadResult?>? read=null,ModuleExecutionScope? scope=null){var plugin=new NPointPlugin();var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());values["TeachEnable"]=JsonSerializer.SerializeToElement(true);var result=plugin.CreateRuntime().ExecuteAsync(new("text",Environment.CurrentDirectory,input,values){ReadTextInput=read,Scope=scope},default).GetAwaiter().GetResult();Check(result.Status==ModuleStatus.Success,"teaching/sampling succeeds");return result;}
 static void Graph(){var plugin=new NPointPlugin();var modules=new ModuleRegistry();new ToolPluginRegistry().Register(plugin,modules);var source=new Source();modules.Register(source.Descriptor,()=>new Source());var doc=new GraphEditorDocument(modules);var sid=doc.AddNode("npoint-text","1",0,0);var target=doc.AddNode(plugin.Manifest.Id,"1.0.0",200,0);doc.ConnectExecution(sid,target);var pid=doc.CurrentProcedureId;ProcedureDocument Flow()=>doc.Document.Procedures.Single(p=>p.Id==pid);var values=Flow().Nodes.Single(n=>n.Id==target).Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());values["TeachEnable"]=JsonSerializer.SerializeToElement(true);doc.SetProcedureNodeParameters(pid,target,values);var service=new WorkflowConfigurationSubscriptionService(Flow,modules,target,(d,r)=>doc.SetProcedureInputSubscription(pid,target,d.Name,r));foreach(string name in new[]{"ImagePointX","ImagePointY","PhysicalPointX","PhysicalPointY","WorldRotateAngle","Trigger","TeachFlagInput"}){string type=name is "Trigger" or "TeachFlagInput"?"string":"float";var result=service.Bind(new(ConfigurationSubscriptionDomain.InputIo,name,type),new(new ConfigurationOutputReference(pid,sid,name,type),ConfigurationSubscriptionIndex.All));Check(result.Status==ConfigurationSubscriptionStatus.Available,"actual typed array binds "+name);}using var scope=new ModuleExecutionScope();var run=new GraphExecutor(modules).RunAsync(Flow(),Environment.CurrentDirectory,scope:scope).GetAwaiter().GetResult().Nodes.Single(n=>n.NodeId==target);Check(run.Status==NodeRunStatus.Success&&run.Outputs["CalibCurIndex"].As<long>()==0,"actual string-array graph uses index0 matching teach and does not sample");}
 sealed class Source:IModule{
  public ModuleDescriptor Descriptor{get;}=new("npoint-text","1","Text",[],new[]{"ImagePointX","ImagePointY","PhysicalPointX","PhysicalPointY","WorldRotateAngle"}.Select(n=>new PortDescriptor(n,DataKind.NumberArray)).Concat(new[]{new PortDescriptor("Trigger",DataKind.Text){Cardinality=ValueCardinality.Array},new PortDescriptor("TeachFlagInput",DataKind.Text){Cardinality=ValueCardinality.Array}}).ToArray(),[]);
  public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken t){var input=Inputs();input["Trigger"]=PortValue.TextArray(["go","first-other"]);input["TeachFlagInput"]=PortValue.TextArray(["go","second-other"]);return ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,input));}
 }
 sealed class Reader:IToolTextInputReader{public int Calls;public ToolTextInputReadResult Read(ModuleExecutionContext c,string n,int index,int capacity){Calls++;Check(index==0&&capacity==512,"scope receives source arguments");return new(0,1,"go",3);}}
}
